# ガーデンアーチ（arch）：いまの絵と同じデザイン・同じ大きさ。木の柱4本の上に、前とうしろの横木、その上に、おく向きのたる木6本。つるばらが横木と右の柱にからまり、白い花がさく。
# 設計図（じっさいに作れる組み方。単位はマス。大きさは、いまの絵（113×126ドット）に合わせた。1マスに置き、左右へはみ出す）
#   柱：木の角柱4本（0.10角・高さ0〜1.55）。x=-0.25 と 1.20、y=0.30 と 0.80。地面にうめてたてる。
#   横木：前とうしろに1本ずつ（木の角材 0.08×0.12、x=-0.36〜1.31・高さ1.50〜1.62）。柱の上にのせて、ほぞでとめる。
#   たる木：おく向きの木の板6本（はば0.06・高さ0.10・長さ0.78、y=0.16〜0.94・高さ1.62〜1.72）。x=-0.24〜1.19 に同じ間かくで。横木の上にのせて、くぎでとめる。
#   つるばら：お手本の絵の葉・花の所から読みとった場所に、葉（みんな同じ色・輪郭線はうすく）と白いばら。茎は細く（太さ0.005）、葉と同じ色で、となりの葉どうしをつなぐ。右の前の柱のつるは、いちばん下の葉でおわる。
from blueprint import Part as P
from common import *
import math
ID='arch';BOTTOM=63;GRAD=True
VIEWS=[('arch',0),('arch>1',3)]   # 横・縦（ROTS 2）
Y0,Y1=0.3225,0.7775;XL,XR=-0.25,1.20;LEAF=(172,190,86);ROSE=(248,240,229)   # 葉・花の色は、お手本の絵の色
LEAVES= [(1.035, 0.365, 1.565), (1.082, 0.361, 1.565), (1.027, 0.416, 1.565), (1.098, 0.42, 1.565), (0.721, 0.51, 1.565), (0.774, 0.502, 1.565), (0.956, 0.515, 1.565), (1.113, 0.494, 1.565), (1.234, 0.504, 1.565), (1.282, 0.5, 1.565), (0.265, 0.577, 1.565), (0.47, 0.571, 1.565), (0.527, 0.581, 1.565), (0.734, 0.577, 1.565), (0.784, 0.573, 1.565), (0.965, 0.573, 1.565), (1.031, 0.6, 1.565), (1.099, 0.581, 1.565), (1.145, 0.583, 1.565), (0.237, 0.643, 1.565), (0.263, 0.639, 1.565), (1.038, 0.643, 1.565), (1.088, 0.632, 1.565), (0.409, 0.813, 1.565), (0.453, 0.806, 1.565), (0.595, 0.8, 1.565), (0.643, 0.797, 1.565), (0.79, 0.802, 1.565), (0.82, 0.797, 1.565), (0.924, 0.797, 1.565), (0.97, 0.807, 1.565), (1.331, 0.818, 1.565), (0.282, 0.866, 1.565), (0.346, 0.87, 1.565), (0.401, 0.866, 1.565), (0.476, 0.865, 1.565), (0.531, 0.866, 1.565), (0.593, 0.846, 1.565), (0.652, 0.868, 1.565), (0.717, 0.866, 1.565), (0.781, 0.861, 1.565), (0.967, 0.88, 1.565), (1.032, 0.877, 1.565), (1.234, 0.875, 1.565), (1.282, 0.871, 1.565), (1.335, 0.859, 1.565), (-0.143, 0.929, 1.565), (-0.027, 0.926, 1.565), (0.231, 0.921, 1.565), (0.268, 0.914, 1.565), (0.401, 0.932, 1.565), (0.465, 0.924, 1.565), (0.531, 0.922, 1.565), (0.718, 0.926, 1.565), (0.779, 0.934, 1.565), (0.907, 0.939, 1.565), (0.965, 0.934, 1.565), (1.031, 0.929, 1.565), (1.098, 0.936, 1.565), (1.234, 0.926, 1.565), (1.281, 0.926, 1.565), (0.951, 0.85, 1.453), (0.971, 0.86, 1.329), (1.031, 0.86, 1.331), (0.856, 0.86, 1.278), (0.906, 0.86, 1.284), (0.968, 0.86, 1.28), (1.031, 0.86, 1.281), (1.081, 0.86, 1.287), (1.304, 0.86, 1.28), (1.326, 0.86, 1.277), (0.963, 0.86, 1.238), (1.338, 0.86, 1.216), (1.304, 0.86, 1.16), (1.34, 0.86, 1.158), (1.148, 0.86, 1.082), (1.218, 0.86, 1.101), (1.296, 0.86, 1.106), (1.342, 0.86, 1.106), (1.101, 0.86, 1.04), (1.159, 0.86, 1.03), (1.201, 0.86, 1.024), (1.168, 0.86, 0.99), (1.218, 0.86, 0.972), (1.281, 0.86, 0.954), (1.332, 0.86, 0.962), (1.229, 0.86, 0.907), (1.273, 0.86, 0.908), (1.342, 0.86, 0.907), (1.152, 0.86, 0.819), (1.295, 0.86, 0.846), (1.327, 0.86, 0.846), (1.096, 0.86, 0.783), (1.304, 0.86, 0.77), (1.218, 0.86, 0.689), (1.295, 0.86, 0.698), (1.334, 0.86, 0.694), (1.221, 0.86, 0.63), (1.281, 0.86, 0.628), (1.329, 0.86, 0.645), (1.163, 0.86, 0.533), (1.232, 0.86, 0.565), (1.156, 0.86, 0.496), (1.202, 0.86, 0.5), (1.304, 0.86, 0.405), (1.326, 0.86, 0.409)]
ROSES= [(1.031, 0.5, 1.565), (0.515, 0.762, 1.565), (0.843, 0.883, 1.565), (1.281, 0.86, 1.035), (1.171, 0.86, 0.752)]

def PARTS():
    L=[]
    for nx,x in(('左',XL),('右',XR)):
        for ny,y in(('前',Y1),('うしろ',Y0)):L.append(P('柱（%s%s）'%(nx,ny),'box',(x-0.05,y-0.05,0.0,x+0.05,y+0.05,1.39),WOOD,bevel=0.01,note='地面にうめてたてる'))
    for ny,y in(('前',Y1),('うしろ',Y0)):
        L.append(P('横木（%s）'%ny,'box',(-0.36,y-0.04,1.333,1.31,y+0.04,1.453),WOOD,bevel=0.012,on=('柱（左%s）'%ny,'柱（右%s）'%ny),note='柱の上にのせて、ほぞでとめる'))
    for i in range(6):
        x=XL+0.01+(XR-XL-0.02)*i/5
        L.append(P('たる木%d'%(i+1),'box',(x-0.03,0.22,1.453,x+0.03,0.88,1.553),WOOD,bevel=0.01,on=('横木（前）','横木（うしろ）'),note='横木の上にのせて、くぎでとめる'))
    # つるばら：お手本の絵の葉・花の所から読みとった場所（たる木の上・前の横木からたれる所・右の前の柱）に、葉と白いばら。茎は細く（0.005）、葉と同じ色。となりの葉どうしを茎でつなぐ（いちばん近い葉へ、木の枝わかれの形）
    post=lambda q:q[1]>0.8 and q[2]<1.3   # 右の柱と、前の横木からたれる所
    KEEP=[q for k,q in enumerate(LEAVES) if (k%5 in(0,2) if post(q) else k%3!=2)]   # 葉：お手本の場所から、上は3まいに2まい・柱は5まいに2まい（つまりすぎないように）
    pts=KEEP+ROSES;n=len(pts);d=lambda a,b:math.dist(pts[a],pts[b])
    par={0:None};left=set(range(1,n))
    while left:   # 茎：のこした葉と花どうしを、枝わかれの形（さいしょうの木）でつなぐ
        a,b=min(((a,b) for a in par for b in left),key=lambda e:d(*e));par[b]=a;left.remove(b)
    for b,a in par.items():
        if a is None or d(a,b)>0.25:continue
        q=notex(P('茎%d'%b,'tube',([pts[a],pts[b]],0.005),LEAF,deco=True,note='細い茎'));q.olk=0.86;L.append(q)
    for k,(x,y,z) in enumerate(KEEP):   # 葉：みんな同じ色（お手本の葉の色）。大きさと向きを少しずつかえる
        sz=1.0+0.18*math.sin(k*2.3)
        q=notex(P('葉%d'%(k+1),'egg',(x,y,z+0.015,0.055*sz,0.034*sz,0.014,(k*53)%180),LEAF,deco=True,note='つるの葉'));q.olk=0.86;L.append(q)
    for k,(x,y,z) in enumerate(ROSES):   # 白いばら：白1色の、まるい花びらのかたまり（トリポのばらは、この大きさでは形がくずれるので、まるい形で）。輪郭線はうすく（お手本の色）
        q=notex(P('花%d'%(k+1),'ball',(x,y+0.01,z+0.035,0.05,0.7),ROSE,deco=True,note='白いばら'));q.olk=0.84;q.soft1=True;q.grp='花%d'%(k+1);L.append(q)
        for a in range(5):
            r_=a*2*math.pi/5+k;q=notex(P('花びら%d-%d'%(k+1,a+1),'ball',(x+0.04*math.cos(r_),y+0.01+0.04*math.sin(r_),z+0.03,0.028,0.7),ROSE,deco=True,note='花びら'));q.olk=0.84;q.soft1=True;q.grp='花%d'%(k+1);L.append(q)
    return L
